export type ParsedChartSeriesFormula = {
  bubbleSizeFormula?: string;
  categoryFormula: string;
  nameFormula?: string;
  nameLiteral?: string;
  order: number;
  valueFormula: string;
};

function quoteSeriesFormulaString(value: string) {
  return `"${value.replace(/"/g, "\"\"")}"`;
}

function unquoteSeriesFormulaString(value: string) {
  const trimmed = value.trim();
  if (trimmed.length < 2 || !trimmed.startsWith("\"") || !trimmed.endsWith("\"")) {
    return null;
  }

  return trimmed.slice(1, -1).replace(/""/g, "\"");
}

function splitTopLevelSeriesArguments(value: string) {
  const args: string[] = [];
  let current = "";
  let doubleQuoted = false;
  let singleQuoted = false;
  let depth = 0;

  for (let index = 0; index < value.length; index += 1) {
    const char = value[index] ?? "";
    const next = value[index + 1] ?? "";

    if (doubleQuoted) {
      current += char;
      if (char === "\"" && next === "\"") {
        current += next;
        index += 1;
      } else if (char === "\"") {
        doubleQuoted = false;
      }
      continue;
    }

    if (singleQuoted) {
      current += char;
      if (char === "'" && next === "'") {
        current += next;
        index += 1;
      } else if (char === "'") {
        singleQuoted = false;
      }
      continue;
    }

    if (char === "\"") {
      doubleQuoted = true;
      current += char;
      continue;
    }

    if (char === "'") {
      singleQuoted = true;
      current += char;
      continue;
    }

    if (char === "(") {
      depth += 1;
      current += char;
      continue;
    }

    if (char === ")") {
      depth = Math.max(0, depth - 1);
      current += char;
      continue;
    }

    if (char === "," && depth === 0) {
      args.push(current.trim());
      current = "";
      continue;
    }

    current += char;
  }

  args.push(current.trim());
  return args;
}

function readSeriesNameFormula(series: XlsxChartSeries) {
  const raw = series.raw && typeof series.raw === "object" ? series.raw as Record<string, unknown> : null;
  return typeof raw?.name === "string" && raw.name.length > 0 ? raw.name : null;
}

export function buildChartSeriesFormula(chart: XlsxChart | null | undefined, seriesIndex: number) {
  const series = chart?.series[seriesIndex];
  if (!chart || !series) {
    return "";
  }

  const nameFormula = readSeriesNameFormula(series);
  const nameArgument = nameFormula ?? quoteSeriesFormulaString(series.name ?? `Series ${seriesIndex + 1}`);
  const categoryArgument = series.categoriesRef?.formula ?? "";
  const valueArgument = series.valuesRef?.formula ?? "";
  const orderArgument = String(seriesIndex + 1);
  const bubbleArgument = series.bubbleSizeRef?.formula;

  return [
    `=SERIES(${nameArgument}`,
    categoryArgument,
    valueArgument,
    orderArgument,
    ...(chart.chartType === "Bubble" || bubbleArgument ? [bubbleArgument ?? ""] : [])
  ].join(",") + ")";
}

export function parseChartSeriesFormula(formula: string, chart: XlsxChart | null | undefined): ParsedChartSeriesFormula | null {
  const trimmed = formula.trim();
  const withoutEquals = trimmed.startsWith("=") ? trimmed.slice(1).trim() : trimmed;
  const match = /^SERIES\s*\(([\s\S]*)\)$/i.exec(withoutEquals);
  if (!match) {
    return null;
  }

  const args = splitTopLevelSeriesArguments(match[1]);
  const isBubble = chart?.chartType === "Bubble";
  if (args.length < 4 || args.length > 5 || (isBubble && args.length !== 5)) {
    return null;
  }

  const [nameArg = "", categoryFormula = "", valueFormula = "", orderArg = "", bubbleSizeFormula] = args;
  if (!categoryFormula || !valueFormula) {
    return null;
  }

  const parsedOrder = Number(orderArg);
  if (!Number.isFinite(parsedOrder)) {
    return null;
  }

  const nameLiteral = unquoteSeriesFormulaString(nameArg);
  return {
    bubbleSizeFormula: bubbleSizeFormula && bubbleSizeFormula.length > 0 ? bubbleSizeFormula : undefined,
    categoryFormula,
    nameFormula: nameLiteral == null && nameArg.length > 0 ? nameArg : undefined,
    nameLiteral: nameLiteral ?? undefined,
    order: parsedOrder,
    valueFormula
  };
}

export function applyChartSeriesFormula(
  chart: XlsxChart,
  seriesIndex: number,
  formula: string,
  workbook: Workbook | null
) {
  const parsed = parseChartSeriesFormula(formula, chart);
  const currentSeries = chart.series[seriesIndex];
  if (!parsed || !currentSeries) {
    return null;
  }

  const categoriesRef: XlsxChartReference = {
    ...(currentSeries.categoriesRef ?? {}),
    formula: parsed.categoryFormula,
    values: parsed.categoryFormula === currentSeries.categoriesRef?.formula ? currentSeries.categoriesRef.values : undefined
  };
  const valuesRef: XlsxChartReference = {
    ...(currentSeries.valuesRef ?? {}),
    formula: parsed.valueFormula,
    values: parsed.valueFormula === currentSeries.valuesRef?.formula ? currentSeries.valuesRef.values : undefined
  };
  const bubbleSizeRef: XlsxChartReference | null = chart.chartType === "Bubble" || parsed.bubbleSizeFormula
    ? {
        ...(currentSeries.bubbleSizeRef ?? {}),
        formula: parsed.bubbleSizeFormula,
        values: parsed.bubbleSizeFormula === currentSeries.bubbleSizeRef?.formula ? currentSeries.bubbleSizeRef?.values : undefined
      }
    : currentSeries.bubbleSizeRef ?? null;
  const isUnresolved = (formula: string | undefined) => Boolean(
    workbook && formula && !resolveReferenceSheet(workbook, chart.workbookSheetIndex, formula).sheet
  );
  const resolveEditedReference = (
    reference: XlsxChartReference | null,
    currentReference: XlsxChartReference | null | undefined,
    currentValues: Array<number | string | null>,
    mode: "category" | "value"
  ) => {
    if (!workbook) return currentValues;
    if (reference?.formula === currentReference?.formula && isUnresolved(reference?.formula)) return currentValues;
    return resolveReferenceValues(workbook, chart.workbookSheetIndex, reference, mode);
  };
  const raw: Record<string, unknown> = {
    ...(currentSeries.raw ?? {}),
    unresolvedCategoriesReference: isUnresolved(categoriesRef.formula),
    unresolvedValuesReference: isUnresolved(valuesRef.formula),
    unresolvedBubbleSizeReference: isUnresolved(bubbleSizeRef?.formula),
    unresolvedNameReference: isUnresolved(parsed.nameFormula)
  };
  if (parsed.nameFormula) {
    raw.name = parsed.nameFormula;
  } else {
    delete raw.name;
  }

  const categories = resolveEditedReference(categoriesRef, currentSeries.categoriesRef, currentSeries.categories, "category");
  raw.chartCategoryReferenceValues = categories;
  raw.chartCategoryNumericValues = workbook
    ? resolveReferenceValues(workbook, chart.workbookSheetIndex, categoriesRef, "value")
    : currentSeries.raw?.chartCategoryNumericValues;
  const nextSeries: XlsxChartSeries = {
    ...currentSeries,
    bubbleSizeRef,
    bubbleSizes: resolveEditedReference(bubbleSizeRef, currentSeries.bubbleSizeRef, currentSeries.bubbleSizes ?? [], "value")
      .map((value) => typeof value === "number" && Number.isFinite(value) ? value : null),
    categories,
    categoriesRef,
    name: parsed.nameLiteral ?? (
      parsed.nameFormula === currentSeries.raw?.name && isUnresolved(parsed.nameFormula)
        ? currentSeries.name
        : parsed.nameFormula && workbook
          ? resolveSeriesName(workbook, chart.workbookSheetIndex, parsed.nameFormula)
          : parsed.nameFormula ?? currentSeries.name
    ),
    raw,
    values: resolveEditedReference(valuesRef, currentSeries.valuesRef, currentSeries.values, "value")
      .map((value) => typeof value === "number" && Number.isFinite(value) ? value : null),
    valuesRef
  };

  const hierarchy = currentSeries.raw?.chartHierarchyCategories as Array<Array<{ level: number; label: string }>> | undefined;
  if (hierarchy) {
    const changedReference = categoriesRef.formula !== currentSeries.categoriesRef?.formula;
    const resolvedHierarchy = changedReference ? buildEditedChartHierarchy(nextSeries) : hydrateChartHierarchy(nextSeries, hierarchy);
    if (resolvedHierarchy) {
      raw.chartHierarchyCategories = resolvedHierarchy;
      nextSeries.categories = resolvedHierarchy.map((point) => point?.find((entry) => entry.level === 0)?.label ?? null);
    } else delete raw.chartHierarchyCategories;
  }

  const sourceSeries = chart.raw?.officeSourceSeries as XlsxChartSeries[] | undefined;
  return {
    ...chart,
    raw: sourceSeries ? { ...chart.raw, officeSourceSeries: sourceSeries.map(series => series.id === currentSeries.id ? nextSeries : series) } : chart.raw,
    series: chart.series.map((series, index) => index === seriesIndex ? nextSeries : series),
    typeGroups: chart.typeGroups?.map((group) => ({
      ...group,
      series: group.series.map((series) => series.id === currentSeries.id ? nextSeries : series)
    }))
  };
}

